import sqlite3


class UserLoginDB:
    def __init__(self, db_name):
        self.connection = sqlite3.connect(db_name)
        self.cursor = self.connection.cursor()

    def _execute_insert(self, sql, params):
        self.cursor.execute(sql, params)
        self.connection.commit()

    def _execute_delete(self, sql, params):
        self.cursor.execute(sql, params)
        self.connection.commit()

    def _fetch_user_by_username(self, username):
        self.cursor.execute('''
            SELECT * FROM users WHERE username = ?
        ''', (username,))
        return self.cursor.fetchone()

    def insert_user(self, username, password):
        sql = '''
            INSERT INTO users (username, password)
            VALUES (?, ?)
        '''
        self._execute_insert(sql, (username, password))

    def search_user_by_username(self, username):
        return self._fetch_user_by_username(username)

    def delete_user_by_username(self, username):
        sql = '''
            DELETE FROM users WHERE username = ?
        '''
        self._execute_delete(sql, (username,))

    def _is_valid_user_password(self, user, password):
        return user is not None and user[1] == password

    def validate_user_login(self, username, password):
        user = self._fetch_user_by_username(username)
        return self._is_valid_user_password(user, password)
